<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoTipoPlanilla, guardarTipoPlanilla, listarRegimenesActivos, listarTiposPlanilla, periodicidades } from '../services/tiposPlanilla'
import type { RegimenOption, TipoPlanilla, TipoPlanillaPayload } from '../interfaces/tiposPlanilla.interface'

const rows=ref<TipoPlanilla[]>([]),regimenes=ref<RegimenOption[]>([]),criterio=ref(''),regimenFiltro=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const defaults:TipoPlanillaPayload={codigo:'',descripcion:'',periodicidad:'Mensual',regimen_id:null}
const form=reactive<TipoPlanillaPayload>({...defaults})
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'

async function load(next=1){loading.value=true;error.value='';try{const result=await listarTiposPlanilla(criterio.value,regimenFiltro.value,next);rows.value=result.data;page.value=result.current_page;lastPage.value=result.last_page;total.value=result.total}catch(value){error.value=message(value)}finally{loading.value=false}}
async function loadRegimenes(){try{regimenes.value=await listarRegimenesActivos()}catch(value){error.value=message(value)}}
function open(item?:TipoPlanilla){editing.value=item?.id??null;Object.assign(form,item?{codigo:item.codigo,descripcion:item.descripcion,periodicidad:item.periodicidad,regimen_id:item.regimen_id}:{...defaults});error.value='';modal.value=true}
function validate(){if(form.codigo.trim().length<2)return 'El código debe tener al menos 2 caracteres.';if(form.codigo.trim().length>10)return 'El código admite como máximo 10 caracteres.';if(form.descripcion.trim().length<3)return 'La descripción debe tener al menos 3 caracteres.';if(form.descripcion.trim().length>150)return 'La descripción admite como máximo 150 caracteres.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarTipoPlanilla(editing.value,{...form,codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim().toUpperCase()});modal.value=false;success.value=`Tipo de planilla ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:TipoPlanilla){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} el tipo de planilla ${item.descripcion}?`))return;try{const result=await cambiarEstadoTipoPlanilla(item.id);item.estado=result.estado;success.value=result.message??`Tipo de planilla ${item.estado?'activado':'desactivado'} correctamente.`}catch(value){error.value=message(value)}}
function clearFilters(){criterio.value='';regimenFiltro.value=null;load(1)}
onMounted(()=>Promise.all([load(),loadRegimenes()]))
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Tipos de planilla</nav><header class="hero"><div class="mark">TP</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Tipos de planilla</h1><p>Periodicidad y régimen aplicable para el procesamiento de planillas.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo tipo</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar<input v-model.trim="criterio" placeholder="Código, descripción o periodicidad"></label><label>Régimen<select v-model="regimenFiltro"><option :value="null">Todos los regímenes</option><option v-for="item in regimenes" :key="item.id" :value="item.id">{{item.codigo}} · {{item.descripcion}}</option></select></label><button>Buscar</button><button type="button" class="soft" @click="clearFilters">Limpiar</button></form><section class="table-card"><header><div><small>CONFIGURACIÓN DE PLANILLAS</small><h2>Tipos registrados</h2></div></header><div v-if="loading" class="empty">Consultando tipos de planilla…</div><div v-else-if="!rows.length" class="empty">No se encontraron tipos de planilla.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Descripción</th><th>Régimen</th><th>Periodicidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}</td><td>{{item.regimen?`${item.regimen.codigo} · ${item.regimen.descripcion}`:'TODOS'}}</td><td><span class="period">{{item.periodicidad}}</span></td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">TP</div><div><small>CONFIGURACIÓN DE PLANILLAS</small><h2>{{editing?'Editar':'Registrar'}} tipo de planilla</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="10" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Periodicidad *<select v-model="form.periodicidad"><option v-for="item in periodicidades" :key="item" :value="item">{{item}}</option></select></label><label class="span2">Descripción *<input v-model="form.descripcion" maxlength="150" @input="form.descripcion=form.descripcion.toUpperCase()"></label><label class="span2">Régimen aplicable<select v-model="form.regimen_id"><option :value="null">TODOS LOS REGÍMENES</option><option v-for="item in regimenes" :key="item.id" :value="item.id">{{item.codigo}} · {{item.descripcion}}</option></select><small>Si no selecciona uno, el tipo estará disponible para todos los regímenes.</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#7357b6;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#f2edff;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{min-width:260px;font-size:.52rem}.filters label:first-child{margin-right:auto;width:min(420px,100%)}.filters input,.filters select,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive,.period{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.period{color:#60479f;background:#f2edff}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(650px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.span2{grid-column:span 2}.dialog label small{margin-top:5px;color:#7e8a90;font-weight:400}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%;min-width:0}.grid{grid-template-columns:1fr}.span2{grid-column:auto}.actions{min-width:140px}}
</style>
